use std::sync::{mpsc::sync_channel, Arc, Mutex};
use std::thread;

fn sender(m: Arc<Mutex<()>>, ch_tx: std::sync::mpsc::SyncSender<i32>) {
    {
        let _guard = m.lock().unwrap();
    }
    ch_tx.send(1).unwrap();
    ch_tx.send(2).unwrap();
}

fn receiver(m: Arc<Mutex<()>>, ch_rx: std::sync::mpsc::Receiver<i32>) {
    {
        let _guard = m.lock().unwrap();
    }
    let v1 = ch_rx.recv().unwrap();
    let v2 = ch_rx.recv().unwrap();
    let _ = (v1, v2);
}

fn main() {
    let m = Arc::new(Mutex::new(()));
    let (ch_tx, ch_rx) = sync_channel(1);

    let m_sender = Arc::clone(&m);
    let sender_handle = thread::spawn(move || sender(m_sender, ch_tx));

    let m_receiver = Arc::clone(&m);
    let receiver_handle = thread::spawn(move || receiver(m_receiver, ch_rx));

    sender_handle.join().unwrap();
    receiver_handle.join().unwrap();

    println!("DONE done=1");
}
